def solution(friends, gifts):
    from collections import defaultdict

    gift_count = {friend: [0] * len(gifts) for friend in set(''.join(gifts))}

    for i in range(len(gifts)):
        sender, receiver = gifts[i].split()
        if (sender != 'me' and receiver == 'you') or (receiver != 'me' and sender == 'you'):
            continue

        index = i // len(friends)

        if sender not in ['me', 'you']:
            gift_count[sender][index] += 1

        if receiver not in ['me', 'you']:
            gift_count[receiver][index] -= 1

    total_gift_counts = list(map(sum, zip(*gift_count.values())))
    max_index = total_gift_counts.index(max(total_gift_counts))

    return sum(1 for count in total_gift_counts[max_index + 1:] if count > 0)

